UPDATE userWareHouse
SET ware_end_date = CASE

    WHEN ware_id = #{item.wareId}
     AND warehouse_pos_x = #{item.warehousePosX}
     AND warehouse_pos_y = #{item.warehousePosY}
     AND client_id = #{item.clientID}
    THEN #{item.wareEndDate}

END
WHERE (ware_id, warehouse_pos_x, warehouse_pos_y, client_id) IN

    (#{item.wareId}, #{item.warehousePosX}, #{item.warehousePosY}, #{item.clientID})
